<template>
  <section class="expense-page" dir="rtl">
    <header class="expense-hero">
      <div><nav class="breadcrumbs"><RouterLink to="/dashboard">داشبورد</RouterLink><span>/</span><strong>مدیریت هزینه‌ها</strong></nav><p class="eyebrow">حسابداری روزانه</p><h1>هزینه‌ها</h1><p>ثبت و پیگیری هزینه‌ها، بررسی مبالغ در بازه زمانی و مشاهده گزارش دسته‌بندی‌ها.</p></div>
      <div class="hero-actions"><RouterLink class="secondary" to="/dashboard/cost-control/overheads">هزینه‌های سربار</RouterLink><RouterLink class="secondary" to="/dashboard/cost-control/expense-categories">دسته‌بندی‌ها</RouterLink><button class="primary create-button" @click="openCreate"><span>＋</span><strong>ثبت هزینه</strong></button></div>
    </header>

    <section class="summary-grid" aria-label="خلاصه هزینه‌ها">
      <article :class="{skeleton:loadingSummary}"><template v-if="!loadingSummary"><span>کل هزینه در بازه</span><strong>{{money(summary.total_expenses)}}</strong><small>{{rangeLabel}} · {{number(summary.expense_count)}} مورد</small></template></article>
      <button :class="{skeleton:loadingSummary,active:filters.payment_status==='paid'}" @click="setStatus('paid')"><template v-if="!loadingSummary"><span>پرداخت‌شده</span><strong class="success">{{money(summary.paid_total)}}</strong><small>مشاهده هزینه‌های تسویه‌شده ←</small></template></button>
      <button :class="{skeleton:loadingSummary,active:filters.payment_status==='pending'}" @click="setStatus('pending')"><template v-if="!loadingSummary"><span>در انتظار پرداخت</span><strong class="warning">{{money(summary.unpaid_total)}}</strong><small>پیگیری پرداخت‌های باز ←</small></template></button>
      <article :class="{skeleton:loadingSummary}"><template v-if="!loadingSummary"><span>میانگین هر هزینه</span><strong>{{money(summary.average_expense)}}</strong><small>در فیلتر فعلی</small></template></article>
    </section>

    <section class="expense-browser">
      <header class="browser-heading"><div><h2>سوابق هزینه‌ها</h2><p>{{number(pagination.count)}} نتیجه{{activeFilterCount?` با ${number(activeFilterCount)} فیلتر فعال`:''}}</p></div><button class="refresh-button" :disabled="loading" @click="refresh" aria-label="به‌روزرسانی">↻</button></header>
      <div class="search-row"><label class="search-box"><span>⌕</span><input v-model.trim="draftFilters.search" placeholder="جستجو در عنوان، توضیحات یا شماره مرجع" @input="debouncedSearch"/><button v-if="draftFilters.search" type="button" @click="clearSearch">×</button></label><button class="filter-toggle" :class="{active:filtersOpen||activeFilterCount}" @click="filtersOpen=!filtersOpen">فیلترها <b v-if="activeFilterCount">{{number(activeFilterCount)}}</b></button></div>
      <form v-if="filtersOpen" class="filter-panel" @submit.prevent="applyFilters"><label>دسته‌بندی<select v-model="draftFilters.category"><option value="">همه دسته‌ها</option><option v-for="category in categories" :key="category.id" :value="category.id">{{category.name}}</option></select></label><label>وضعیت پرداخت<select v-model="draftFilters.payment_status"><option value="">همه وضعیت‌ها</option><option value="paid">پرداخت‌شده</option><option value="pending">در انتظار پرداخت</option><option value="cancelled">لغوشده</option></select></label><label>روش پرداخت<select v-model="draftFilters.payment_method"><option value="">همه روش‌ها</option><option value="cash">نقدی</option><option value="card">کارت‌خوان</option><option value="transfer">انتقال بانکی</option><option value="online">آنلاین</option><option value="other">سایر</option></select></label><label>از تاریخ<JalaliDatePicker v-model="draftFilters.start_date" placeholder="شروع بازه"/></label><label>تا تاریخ<JalaliDatePicker v-model="draftFilters.end_date" placeholder="پایان بازه"/></label><label>مرتب‌سازی<select v-model="draftFilters.ordering"><option value="-date">جدیدترین</option><option value="date">قدیمی‌ترین</option><option value="-amount">بیشترین مبلغ</option><option value="amount">کمترین مبلغ</option><option value="title">عنوان</option></select></label><div class="filter-actions"><button class="primary">اعمال فیلترها</button><button type="button" class="text-button" @click="resetFilters">پاک کردن همه</button></div></form>
      <div v-if="error" class="notice error" role="alert"><span>!</span><div><strong>دریافت اطلاعات ناموفق بود</strong><p>{{error}}</p></div><button @click="refreshAll">تلاش مجدد</button></div>

      <div v-if="loading" class="list-loading"><i></i><span>در حال دریافت هزینه‌ها…</span></div>
      <div v-else-if="!expenses.length" class="empty-state"><span>◎</span><h3>{{activeFilterCount||filters.search?'هزینه‌ای با این فیلترها پیدا نشد':'هنوز هزینه‌ای ثبت نشده است'}}</h3><p>{{activeFilterCount||filters.search?'فیلترها را تغییر دهید یا پاک کنید.':'اولین هزینه روزانه را ثبت کنید تا گزارش‌ها ساخته شوند.'}}</p><button v-if="activeFilterCount||filters.search" class="secondary" @click="resetFilters">پاک کردن فیلترها</button><button v-else class="primary" @click="openCreate">ثبت اولین هزینه</button></div>
      <template v-else><div class="table-scroll"><table><thead><tr><th>هزینه</th><th>دسته‌بندی</th><th>مبلغ</th><th>تاریخ</th><th>پرداخت</th><th>مرجع</th><th></th></tr></thead><tbody><tr v-for="expense in expenses" :key="expense.id"><td><strong>{{expense.title}}</strong><small>{{expense.description||'بدون توضیحات'}}</small></td><td><span class="category-pill">{{expense.category_display}}</span></td><td class="amount">{{money(expense.amount)}}</td><td>{{jalaliDate(expense.date)}}</td><td><span :class="['status',expense.payment_status]">{{expense.payment_status_display}}</span><small>{{expense.payment_method_display||'روش نامشخص'}}</small></td><td>{{expense.reference_number||'—'}}</td><td class="actions"><button @click="openEdit(expense)">ویرایش</button><button class="delete" @click="remove(expense)">حذف</button></td></tr></tbody></table></div>
      <div class="expense-cards"><article v-for="expense in expenses" :key="expense.id"><header><div><strong>{{expense.title}}</strong><span class="category-pill">{{expense.category_display}}</span></div><b>{{money(expense.amount)}}</b></header><p v-if="expense.description">{{expense.description}}</p><dl><div><dt>تاریخ</dt><dd>{{jalaliDate(expense.date)}}</dd></div><div><dt>وضعیت</dt><dd><span :class="['status',expense.payment_status]">{{expense.payment_status_display}}</span></dd></div><div><dt>روش پرداخت</dt><dd>{{expense.payment_method_display||'نامشخص'}}</dd></div><div v-if="expense.reference_number"><dt>مرجع</dt><dd>{{expense.reference_number}}</dd></div></dl><footer><button @click="openEdit(expense)">ویرایش</button><button class="delete" @click="remove(expense)">حذف</button></footer></article></div></template>
      <footer v-if="pagination.count" class="pagination"><span>صفحه {{number(pagination.page)}} از {{number(pagination.total_pages)}}</span><label>تعداد در صفحه<select :value="filters.page_size" @change="setPageSize(Number($event.target.value))"><option :value="10">۱۰</option><option :value="20">۲۰</option><option :value="50">۵۰</option></select></label><div><button :disabled="!pagination.has_previous||loading" @click="goPage(pagination.page-1)">قبلی</button><button :disabled="!pagination.has_next||loading" @click="goPage(pagination.page+1)">بعدی</button></div></footer>
    </section>

    <section class="insights"><article><header><h2>مجموع هزینه هر دسته</h2><small>{{rangeLabel}}</small></header><button v-for="item in summary.category_breakdown" :key="item.category_id" type="button" class="insight-row category-breakdown" @click="filterByCategory(item.category_id)"><span>{{item.category__name}}</span><strong>{{money(item.total)}}</strong><small>{{number(item.count)}} مورد · مشاهده هزینه‌ها ←</small></button><p v-if="!summary.category_breakdown?.length">در این بازه هزینه‌ای وجود ندارد.</p></article><article><header><h2>روند شش ماه اخیر</h2><small>مجموع ماهانه</small></header><div v-for="row in monthly" :key="`${row.year}-${row.month}`" class="insight-row"><span>{{jalaliMonth(row.year,row.month)}}</span><strong>{{money(row.total)}}</strong><small>{{number(row.count)}} مورد</small></div><p v-if="!monthly.length">گزارش ماهانه‌ای وجود ندارد.</p></article></section>
    <ExpenseModal v-model="modalOpen" :expense="editingExpense" :categories="categories" :loading="saving" :server-error="modalError" :field-errors="modalFieldErrors" @submit="save" @request-category="openCategoryFromModal"/>
  </section>
</template>
<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue';import { useRouter } from 'vue-router'
import TransactionAPI from '@/api/transaction.api';import ExpenseModal from '@/components/modals/ExpenseModal.vue';import JalaliDatePicker from '@/components/cost/JalaliDatePicker.vue';import { getApiErrorMessage } from '@/api/error'
const blankFilters=()=>({search:'',category:'',payment_status:'',payment_method:'',start_date:'',end_date:'',ordering:'-date',page:1,page_size:10})
const router=useRouter(),filters=reactive(blankFilters()),draftFilters=reactive(blankFilters()),expenses=ref([]),categories=ref([]),monthly=ref([]),loading=ref(false),loadingSummary=ref(false),saving=ref(false),error=ref(''),modalError=ref(''),modalFieldErrors=ref({}),modalOpen=ref(false),editingExpense=ref(null),filtersOpen=ref(false),pagination=reactive({count:0,page:1,total_pages:1,has_next:false,has_previous:false}),summary=reactive({total_expenses:0,paid_total:0,unpaid_total:0,expense_count:0,average_expense:0,category_breakdown:[]});let searchTimer
const params=()=>Object.fromEntries(Object.entries(filters).filter(([,value])=>value!==''&&value!==null)),activeFilterCount=computed(()=>['category','payment_status','payment_method','start_date','end_date'].filter(key=>filters[key]).length)
const number=value=>Number(value||0).toLocaleString('fa-IR'),money=value=>`${number(value)} تومان`,jalaliDate=value=>value?new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',year:'numeric',month:'short',day:'numeric'}).format(new Date(value)):'—',jalaliMonth=(year,month)=>new Intl.DateTimeFormat('fa-IR-u-ca-persian',{timeZone:'Asia/Tehran',year:'numeric',month:'long'}).format(new Date(Date.UTC(year,month-1,1)))
const rangeLabel=computed(()=>filters.start_date&&filters.end_date?`از ${jalaliDate(filters.start_date)} تا ${jalaliDate(filters.end_date)}`:filters.start_date?`از ${jalaliDate(filters.start_date)}`:filters.end_date?`تا ${jalaliDate(filters.end_date)}`:'همه تاریخ‌ها')
async function load(){loading.value=true;error.value='';try{const data=await TransactionAPI.getList(params());expenses.value=data.results||[];Object.assign(pagination,data)}catch(cause){error.value=getApiErrorMessage(cause)}finally{loading.value=false}}async function loadReports(){loadingSummary.value=true;try{const [summaryData,monthlyData]=await Promise.all([TransactionAPI.getSummary(params()),TransactionAPI.getMonthlyReport(params())]);Object.assign(summary,summaryData);monthly.value=monthlyData||[]}catch(cause){error.value=getApiErrorMessage(cause)}finally{loadingSummary.value=false}}async function loadCategories(){try{categories.value=await TransactionAPI.getCategoryList({is_active:true})}catch(cause){error.value=getApiErrorMessage(cause)}}async function refresh(){await Promise.all([load(),loadReports()])}async function refreshAll(){await Promise.all([loadCategories(),refresh()])}
function applyFilters(){Object.assign(filters,draftFilters,{page:1});refresh()}function debouncedSearch(){clearTimeout(searchTimer);searchTimer=setTimeout(applyFilters,450)}function clearSearch(){draftFilters.search='';applyFilters()}function resetFilters(){Object.assign(filters,blankFilters());Object.assign(draftFilters,blankFilters());filtersOpen.value=false;refresh()}function setStatus(status){draftFilters.payment_status=filters.payment_status===status?'':status;applyFilters()}function filterByCategory(category){draftFilters.category=category;filtersOpen.value=true;applyFilters();document.querySelector('.expense-browser')?.scrollIntoView({behavior:'smooth'})}function goPage(page){filters.page=page;draftFilters.page=page;load()}function setPageSize(size){filters.page_size=size;filters.page=1;draftFilters.page_size=size;draftFilters.page=1;load()}function openCreate(){editingExpense.value=null;modalError.value='';modalFieldErrors.value={};modalOpen.value=true}function openEdit(expense){editingExpense.value=expense;modalError.value='';modalFieldErrors.value={};modalOpen.value=true}
async function save(form){saving.value=true;modalError.value='';modalFieldErrors.value={};const data={...form,date:`${form.date}T00:00:00`};try{if(editingExpense.value)await TransactionAPI.partialUpdate(editingExpense.value.id,data);else await TransactionAPI.create(data);modalOpen.value=false;await refresh()}catch(cause){modalError.value=getApiErrorMessage(cause);modalFieldErrors.value=cause.cost?.errors||{}}finally{saving.value=false}}async function remove(expense){if(!confirm(`هزینه «${expense.title}» حذف شود؟`))return;try{await TransactionAPI.remove(expense.id);if(expenses.value.length===1&&filters.page>1){filters.page-=1;draftFilters.page=filters.page}await refresh()}catch(cause){error.value=getApiErrorMessage(cause)}}function openCategoryFromModal(){modalOpen.value=false;router.push('/dashboard/cost-control/expense-categories')}
onMounted(refreshAll);onBeforeUnmount(()=>clearTimeout(searchTimer))
</script>
